import{_ as a,a as i,c as e,b as r}from"./chunks/framework.b9WMfGr4.js";const p=JSON.parse('{"title":"2026-08-19-数据库管理系统设计赛","description":"","frontmatter":{"title":"2026-08-19-数据库管理系统设计赛","tags":["数据库","性能优化","竞赛备赛","感言"]},"headers":[],"relativePath":"posts/经验分享/2026-08-19-数据库管理系统设计赛.md","filePath":"posts/经验分享/2026-08-19-数据库管理系统设计赛.md"}'),t={name:"posts/经验分享/2026-08-19-数据库管理系统设计赛.md"};function h(o,l,u,n,d,s){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="_2026-rmdb-数据库管理系统内核开发-参赛有感" tabindex="-1">2026 RMDB 数据库管理系统内核开发 参赛有感 <a class="header-anchor" href="#_2026-rmdb-数据库管理系统内核开发-参赛有感" aria-label="Permalink to &quot;2026 RMDB 数据库管理系统内核开发 参赛有感&quot;">​</a></h1><blockquote><p>时间：2026-08-21</p><p>全文约 7600 字，预计阅读时间约 20 分钟。</p><p>目标读者：参赛新人、赛事主办方</p></blockquote><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#2026-rmdb-数据库管理系统内核开发-参赛有感">2026 RMDB 数据库管理系统内核开发 参赛有感</a><ul><li><a href="#目录">目录</a></li><li><a href="#一写在前面">一、写在前面</a><ul><li><a href="#笔者身份">笔者身份</a></li><li><a href="#赛事说明">赛事说明</a></li><li><a href="#参赛初衷">参赛初衷</a></li><li><a href="#参赛感受">参赛感受</a></li></ul></li><li><a href="#二我的参赛经历">二、我的参赛经历</a><ul><li><a href="#比赛过程">比赛过程</a><ul><li><a href="#前期理论学习">前期理论学习</a></li><li><a href="#队伍分工">队伍分工</a></li><li><a href="#决赛">决赛</a></li><li><a href="#线下赛">线下赛</a></li><li><a href="#答辩">答辩</a></li></ul></li><li><a href="#ai-使用经验">AI 使用经验</a><ul><li><a href="#防止局部最优和重复工作">防止局部最优和重复工作</a></li><li><a href="#明确目标与优化策略">明确目标与优化策略</a></li><li><a href="#审核-ai-输出与任务边界">审核 AI 输出与任务边界</a></li><li><a href="#goal-模式的使用风险">Goal 模式的使用风险</a></li><li><a href="#模型选型">模型选型</a></li></ul></li><li><a href="#性能优化经验">性能优化经验</a></li><li><a href="#做得不好的地方">做得不好的地方</a><ul><li><a href="#团队协作与分工">团队协作与分工</a></li><li><a href="#工程与仓库管理">工程与仓库管理</a></li><li><a href="#ai-使用方式">AI 使用方式</a></li><li><a href="#备赛策略与客观因素">备赛策略与客观因素</a></li></ul></li><li><a href="#比赛的收获">比赛的收获</a><ul><li><a href="#技术认知">技术认知</a></li><li><a href="#工程素养">工程素养</a></li><li><a href="#ai-协作经验">AI 协作经验</a></li></ul></li></ul></li><li><a href="#三给想参赛的新人">三、给想参赛的新人</a><ul><li><a href="#学习路线建议">学习路线建议</a><ul><li><a href="#学习步骤">学习步骤</a></li><li><a href="#学完后再参赛">学完后再参赛</a></li><li><a href="#时间预期与检验标准">时间预期与检验标准</a></li></ul></li><li><a href="#学习资源与技巧">学习资源与技巧</a></li><li><a href="#备赛建议">备赛建议</a></li><li><a href="#适合参赛人群">适合参赛人群</a></li></ul></li><li><a href="#四给主办方的建议">四、给主办方的建议</a><ul><li><a href="#真实感受">真实感受</a></li><li><a href="#具体的建议">具体的建议</a><ul><li><a href="#性能优化阶段">性能优化阶段</a></li><li><a href="#答辩环节">答辩环节</a></li><li><a href="#线下编程赛环节">线下编程赛环节</a></li><li><a href="#赛事制度">赛事制度</a></li><li><a href="#其他方面">其他方面</a></li></ul></li></ul></li><li><a href="#五附录">五、附录</a><ul><li><a href="#线下赛题目">线下赛题目</a></li><li><a href="#答辩记录">答辩记录</a></li><li><a href="#优化技术统计">优化技术统计</a></li><li><a href="#结语">结语</a></li><li><a href="#参考链接">参考链接</a></li></ul></li></ul></li></ul><h2 id="一、写在前面" tabindex="-1">一、写在前面 <a class="header-anchor" href="#一、写在前面" aria-label="Permalink to &quot;一、写在前面&quot;">​</a></h2><h3 id="笔者身份" tabindex="-1">笔者身份 <a class="header-anchor" href="#笔者身份" aria-label="Permalink to &quot;笔者身份&quot;">​</a></h3><p>名称：代双遥 队伍：Coding 身姿如百合花般 学校：西南大学</p><ul><li>零基础内核开发</li><li>2024 级软件工程专业</li><li>已修课课程： <ul><li>C/C++语言</li><li>数据库原理及应用</li><li>数据结构</li><li>操作系统</li><li>计算机网络</li><li>系统分析与设计</li></ul></li><li>职业发展倾向： <ul><li>后端开发</li><li>AI 应用</li><li>Agent 开发</li></ul></li><li>能力： <ul><li>有全栈项目经验</li></ul></li></ul><h3 id="赛事说明" tabindex="-1">赛事说明 <a class="header-anchor" href="#赛事说明" aria-label="Permalink to &quot;赛事说明&quot;">​</a></h3><p>这是一个偏底层的、源码级别的、大型的、贴近真实项目环境的数据库内核开发比赛。比赛时间周期极长，从 5 月到 8 月。</p><p>详细比赛说明请看：<a href="https://os.educg.net/#/index?TYPE=26DB" target="_blank" rel="noreferrer">https://os.educg.net/#/index?TYPE=26DB</a></p><h3 id="参赛初衷" tabindex="-1">参赛初衷 <a class="header-anchor" href="#参赛初衷" aria-label="Permalink to &quot;参赛初衷&quot;">​</a></h3><p>本来我在备战做项目找实习，被同学邀请来打这个比赛。当时想着，既然是数据库的比赛，可以以赛代学，从源码层了解数据库的相关知识。反正都要看数据库的八股文，源码都看了，八股文那还不是手到擒来？</p><p>所以，我主要的初衷就是来学习数据库相关的知识。</p><h3 id="参赛感受" tabindex="-1">参赛感受 <a class="header-anchor" href="#参赛感受" aria-label="Permalink to &quot;参赛感受&quot;">​</a></h3><p>回顾整个参赛过程，最直接的感受是“不确定性”带来的困惑。</p><p>首先是答辩环节的信息不透明：赛前只被告知需要答辩，但答辩的侧重方向、汇报主题、具体时长限制等关键信息都不够明确。更遗憾的是，这些信息往往到临近节点才有所补充，导致前期准备缺乏方向。</p><p>其次是线下编程赛的未知。与算法竞赛不同，这类比赛很难通过刷题进行针对性准备；在没有明确范围和样例的情况下，备赛几乎无从下手。好在我们还能通过赛事交流群获取一些讨论信息，稍微缓解了这种盲目感。</p><p>一句话总结：这场比赛的备赛体验，很像期末考试不划重点——考试范围、评分标准都要靠参赛者自行推测，结果要么准备过度，要么准备不足。<strong>这种高度不确定对零基础参赛者而言，十分不友好。</strong></p><h2 id="二、我的参赛经历" tabindex="-1">二、我的参赛经历 <a class="header-anchor" href="#二、我的参赛经历" aria-label="Permalink to &quot;二、我的参赛经历&quot;">​</a></h2><h3 id="比赛过程" tabindex="-1">比赛过程 <a class="header-anchor" href="#比赛过程" aria-label="Permalink to &quot;比赛过程&quot;">​</a></h3><p>2026 年比赛一共有多个阶段：</p><ol><li>初赛功能题目实现阶段(只开放 10 个功能实现题目)</li><li>初赛性能优化阶段(功能题目实现通道保持开启)</li><li>Gap</li><li>决赛性能优化阶段(只有初赛的功能全部满分才有资格)</li><li>线下编程赛</li><li>答辩一轮(线下赛通过才有答辩资格，10min 汇报 10min 问答)</li><li>答辩二轮(前 20%队伍才有，重来一次，问答时间更久)</li></ol><p>整个比赛从前期学习到答辩，我的过程大概是这样的。</p><h4 id="前期理论学习" tabindex="-1">前期理论学习 <a class="header-anchor" href="#前期理论学习" aria-label="Permalink to &quot;前期理论学习&quot;">​</a></h4><p>整个框架的内容我都跟 AI 交流提问过，生成了一份非常详细的面向零基础的教程文档。技能库理论学习方面，不同模块的各种实现方法对比都看了一遍；测试流程和测试结果指标也各学了一遍。但总体上，学得很粗略，没有经过实践，都是学了就忘，收获很有限。</p><h4 id="队伍分工" tabindex="-1">队伍分工 <a class="header-anchor" href="#队伍分工" aria-label="Permalink to &quot;队伍分工&quot;">​</a></h4><p>我们队伍基本是各干各的，有啥干啥，发挥各自的特长。我负责了大部分的 PPT，设计 -&gt; 画图 -&gt; 讲解。主要是结合所有相关历史记录，告诉 AI 设计思路，然后让 AI 生成内容，再自己设计排版、梳理内容。由于对代码不了解，PPT 中文字表述有问题时很难调整，所以内容几乎是纯 AI 生成，文字描述带 AI 生成的特征很明显。让 AI 画了很多大的流程图，大部分复刻了下来。总的来说，PPT 有人味，起码能看出是手搓的，但内容确实是 AI 生成的。</p><p>性能优化部分的 PPT 是各自准备的：先让 AI 总结所有优化点，然后分配任务，各自完成对应页，所以风格没有统一。总体效果看起来还不错，但内容质量还有待改善，主要是没经验。</p><p>代码脚本方面，主要做了这些事：AI 写脚本自动在线提测；爬取排行榜数据保存；爬取测试结果保存；TG 机器人自动推送测试结果消息；提测任务队列，本地排队提测；本地代码测试框架；html2md 题目转格式；html2yaml 测试结果指标转 Yaml 保存。另外我还写了一些额外的辅助脚本，比如爬虫脚本。大部分时间都是让 AI 自己跑刷分，谁先跑出来就用谁的。</p><h4 id="决赛" tabindex="-1">决赛 <a class="header-anchor" href="#决赛" aria-label="Permalink to &quot;决赛&quot;">​</a></h4><p>决赛阶段，本来计划好依次分析每个模块，自己看懂每个模块后再让 AI 优化，但最终还是不自觉地让 AI 直接 All in。</p><h4 id="线下赛" tabindex="-1">线下赛 <a class="header-anchor" href="#线下赛" aria-label="Permalink to &quot;线下赛&quot;">​</a></h4><p>线下赛我准备的时间不超过 12 小时，属于是一行代码没写。我把准备思路、押题、准备流程全告诉 Agent，然后 Agent 自己通过上下文分析思考可能会怎么考、考哪些，然后跑文档、出结果。总结就是：整理信息差、定义工作流、跑结果。</p><p>最终的结果是，线下赛精准押题，几乎把所有可能会考的都列出来了，AI 也都实现了一遍。比赛过程中，直接照着文档复制粘贴就过了；连线下赛出的纸质题目、给的测试用例都没 debug，直接提交就过了，约等于靠 AI 直接通过了比赛。</p><p>另外，我线下赛花了几个小时，让 AI 跑了两个 goal 任务，花了 50 块左右的 Deepseek 额度，大概 10 亿 token；另外两个队友花时间真的准备了线下赛的代码，我全靠 AI。</p><h4 id="答辩" tabindex="-1">答辩 <a class="header-anchor" href="#答辩" aria-label="Permalink to &quot;答辩&quot;">​</a></h4><p>答辩阶段没有经验，踩了坑。我花了大量时间在初赛的内容描述上，也花了大量时间美化，但对内容的梳理太少了，导致对内容根本不熟；加上依赖 AI 优化，所以经不起提问。</p><p>当初老师提前对 PPT 进行了指导，指导过程中非常重视“加分项”，当时我根本不理解，答辩结束后才知道加分项的重要性。评委只关注自己感兴趣的，根本不在乎你是怎么想的、你讲得有多好。这个比赛最关注的就是优化策略，怎么提分。</p><p>现在回想起来，这个比赛本身也是有问题的。最终的会议上说的是，比赛的目的是为了培育人才，但答辩时根本不注重过程，只看结果：性能分数高就是厉害，中间曲折探索的过程加不了分（谁不是这样的？对啊，谁不是这样的？？）。这个比赛是本科生赛道，本来学数据库内核开发的人就少，课程也开设得很少，我没有感觉到赛事方对于新人的鼓励。一些新人分享学习数据库开发的心得体会、艰难探索，但在比赛中没什么意义；赛事方既没怎么提供优质的学习资料，又让学生自己摸索，结果就是有实力的靠实力，没实力的靠 AI，门槛高。</p><p>答辩环节甚至连主题都没有，只有一个答辩环节，什么要求都不提前给，时长也是最终才给的。我问了学长，学长说是不限时，也属于是踩坑了。答辩环节和决赛刷分结束时间太近了，又要一边刷分，又要一边准备 PPT，时间管理根本来不及。要不是提前 1 周就开始手搓 PPT，真的等到刷分结束才准备 PPT，除了 AI 生成 PPT 以外，我想不到任何方法来补救。或许其他队伍就是觉得有 AI 能做 PPT，所以才花那么多时间刷分；但我一定会把责任归咎到比赛主办方：时间分配不合理。</p><h3 id="ai-使用经验" tabindex="-1">AI 使用经验 <a class="header-anchor" href="#ai-使用经验" aria-label="Permalink to &quot;AI 使用经验&quot;">​</a></h3><p>这一路用 AI 踩了不少坑，也总结了一些经验。</p><h4 id="防止局部最优和重复工作" tabindex="-1">防止局部最优和重复工作 <a class="header-anchor" href="#防止局部最优和重复工作" aria-label="Permalink to &quot;防止局部最优和重复工作&quot;">​</a></h4><ul><li>防止局部最优解：同一份代码，不同的人用不同提示词，AI 给出的优化策略却相同，容易做重复工作。再加上线上测评服务器的影响(初赛)，优化效果无法体现，AI 就会认为优化无效。</li><li>防止重复工作：每次优化策略都要留痕，成功的、失败的都要留。如果丢弃失败记录，AI 会重复往失败的方向尝试，因为它不知道已经尝试过失败了。</li></ul><h4 id="明确目标与优化策略" tabindex="-1">明确目标与优化策略 <a class="header-anchor" href="#明确目标与优化策略" aria-label="Permalink to &quot;明确目标与优化策略&quot;">​</a></h4><ul><li>让 AI 优化的时候，要有一个具体目标，明确优化哪个方面；不要只给一个结果导向的任务，例如：“完成优化”。</li><li>遵循“先分析思考，再探索尝试验证”的原则，完整的优化流程。(例如：发现问题 -&gt; 分析问题 -&gt; 解决方案 -&gt; 测试验证)</li><li>通用 AI 大模型虽然是通用的，大部分内容都知道，但最好提前准备相关资料和上下文，不要在执行任务的时候才想策略。建议直接把所有策略列出来，直接选、对比测试。</li></ul><h4 id="审核-ai-输出与任务边界" tabindex="-1">审核 AI 输出与任务边界 <a class="header-anchor" href="#审核-ai-输出与任务边界" aria-label="Permalink to &quot;审核 AI 输出与任务边界&quot;">​</a></h4><ul><li>AI 能力也有限：AI 不能保证每次生成的代码都是正确的。写好、写全正确性测试能减少 bug，节约线上测试时间消耗。</li><li>AI 说的不能全听，一定得审核，前提是看得懂。AI 有时候会考虑很多其他内容，例如兼容旧功能、旧版本，这纯属过拟合，任务完成过头了。</li></ul><h4 id="goal-模式的使用风险" tabindex="-1">Goal 模式的使用风险 <a class="header-anchor" href="#goal-模式的使用风险" aria-label="Permalink to &quot;Goal 模式的使用风险&quot;">​</a></h4><ul><li>goal 模式有 bug，别轻易用；不懂 goal 模式的，别乱用。有陷入死循环（空转、消耗 token、无限循环）的风险。</li><li>Goal 模式无限循环的场景说明： <ul><li>当输入 <code>/goal task-content</code> 之后，唯一的目标就是这个 task-content。</li><li>终止 Goal 只有两种场景：AI 认为 task-content 完成了，或者用户手动 Ctrl+C 终止。</li><li>就算用户在对话中发送信息要求终止这个 goal，goal 也不会终止，只会无限循环等待输出。因为 task-content 没有被判定为完成，所以不会自动终止，但会话进度也不会再往下推进。</li><li>当 AI 认为所有方式都尝试过了，但 task-content 仍没有被判定为完成时，也会无限循环：方法用尽，但任务始终没有被判定为完成。</li><li>总结：只要任务没有被完成，goal 就不会被主动终止。因此 goal 模式的任务最好是预期中能完成的，没有无法实现的风险。“优化直到分数达到...”这种任务不确定能否完成，不建议使用。</li><li>task-content 不会因为中途聊天而被修改，只有初次定义 task-content 时才有机会修改。</li><li>Goal 模式也有上下文窗口大小限制，超过之后整个 goal 就废了，连 compact 都做不了。</li></ul></li></ul><h4 id="模型选型" tabindex="-1">模型选型 <a class="header-anchor" href="#模型选型" aria-label="Permalink to &quot;模型选型&quot;">​</a></h4><ul><li>Claude 系列真的强，但是 Deepseek 够用。</li></ul><h3 id="性能优化经验" tabindex="-1">性能优化经验 <a class="header-anchor" href="#性能优化经验" aria-label="Permalink to &quot;性能优化经验&quot;">​</a></h3><ul><li>记录好每次测试结果报告，并对应 git 的 commit hash 值。</li><li>失败和成功都需要记录。</li><li>一个点一个点地优化。</li><li>针对测试指标来优化，做到有依据地优化。</li><li>本地写好正确性测试；性能测试只用线上评测（线上环境跟本地出入太大了）。</li><li>AI 给的优化策略要清晰地知道具体的运行流程。</li></ul><h3 id="做得不好的地方" tabindex="-1">做得不好的地方 <a class="header-anchor" href="#做得不好的地方" aria-label="Permalink to &quot;做得不好的地方&quot;">​</a></h3><p>复盘下来，我们的问题主要集中在<strong>团队协作、工程规范、AI 使用和备赛策略</strong>四个方面。</p><h4 id="团队协作与分工" tabindex="-1">团队协作与分工 <a class="header-anchor" href="#团队协作与分工" aria-label="Permalink to &quot;团队协作与分工&quot;">​</a></h4><ul><li>团队几乎没有明确分工，基本是各自想到什么就做什么，缺少统一规划和任务拆解。这与我的协作习惯相悖；虽然依赖 AI 也能推进，但我很确定，明确分工后效率会高很多。</li><li>队伍规范意识薄弱：虽然定过一些规范，例如 git 提交规范，但落实很差，基本形同虚设；直到决赛阶段反复强调协作问题后才有好转。</li><li>代码测试框架不统一，各用各的，增加了协作和排查成本。</li></ul><h4 id="工程与仓库管理" tabindex="-1">工程与仓库管理 <a class="header-anchor" href="#工程与仓库管理" aria-label="Permalink to &quot;工程与仓库管理&quot;">​</a></h4><ul><li>仓库分支管理混乱：队友只新建分支，从不清理，命名也不统一。</li><li>AI 配置管理混乱：各成员独立维护，切换分支时系统提示词不适用；提示词往往一次性使用，被忽略后也没有备份。</li></ul><h4 id="ai-使用方式" tabindex="-1">AI 使用方式 <a class="header-anchor" href="#ai-使用方式" aria-label="Permalink to &quot;AI 使用方式&quot;">​</a></h4><ul><li>说好先读懂源代码、再由 AI 优化，最终没有执行，变成了 AI 自己优化、自己决策。</li><li>由于缺少对代码的掌控，AI 漏掉了一些明显可优化的点，也做了一些脱离比赛场景的多余优化。例如，AI 把压测环境当成真实应用系统，考虑兼容旧模式，实际并不需要。</li><li>过度依赖 AI：线下比赛也几乎完全依靠 AI 完成，自己真正动手实践和思考不足。</li></ul><h4 id="备赛策略与客观因素" tabindex="-1">备赛策略与客观因素 <a class="header-anchor" href="#备赛策略与客观因素" aria-label="Permalink to &quot;备赛策略与客观因素&quot;">​</a></h4><ul><li>线下赛准备不足，个人几乎没有实际编码，主要靠 AI 完成，比赛收获打折。</li><li>初赛测评系统不稳定，AI 优化效果难以体现，影响了判断和推进节奏。(说不清楚到底是什么问题，就是很邪门)</li></ul><h3 id="比赛的收获" tabindex="-1">比赛的收获 <a class="header-anchor" href="#比赛的收获" aria-label="Permalink to &quot;比赛的收获&quot;">​</a></h3><p>虽然有不少遗憾，但收获也是实实在在的。按<strong>技术认知、工程素养、AI 协作经验</strong>三个方面整理如下。</p><h4 id="技术认知" tabindex="-1">技术认知 <a class="header-anchor" href="#技术认知" aria-label="Permalink to &quot;技术认知&quot;">​</a></h4><ul><li>了解了一个数据库系统的底层框架，相关理论知识理解得更深刻了；不过由于代码主要由 AI 完成，记忆不算深刻，仍然看得快、忘得也快。</li><li>经历了一些以前用 git 没遇到过的冲突处理场景，对版本控制的理解更深入。</li><li>对“职责边界”“生命周期”等概念有了更具体、更深刻的理解，工程能力有所提升。</li></ul><h4 id="工程素养" tabindex="-1">工程素养 <a class="header-anchor" href="#工程素养" aria-label="Permalink to &quot;工程素养&quot;">​</a></h4><ul><li>更认识到看源代码、分析源代码、梳理流程的重要性。只有梳理清楚模块的细节流程，才能更好地掌控代码；只有掌控代码，才能开发出真正优质的系统、功能。掌握代码是成功实践的前提。</li><li>做得快不如做得稳，一件事最好不要返工，一次性做好。</li></ul><h4 id="ai-协作经验" tabindex="-1">AI 协作经验 <a class="header-anchor" href="#ai-协作经验" aria-label="Permalink to &quot;AI 协作经验&quot;">​</a></h4><ul><li>实践了 AI 在专业领域的代码开发效果。AI 的能力仍有局限，真正需要懂行的人来指导；AI 总是自以为对，实际上和现实场景的上下文有出入，需要人来纠正（局部最优解、想太多）。</li><li>对 AI 与人的协作有了更清晰的认识：让 AI 实现 idea，让人自己思考、设计。AI 除了动手以外，只作为助理提意见。AI=助理+苦力，我=老板；最终决策由我来调度，探索、实现等苦力活交给 AI。最完整的上下文只有“我”拥有。</li><li>知道了怎么搞 AI 反代，薅羊毛。</li></ul><h2 id="三、给想参赛的新人" tabindex="-1">三、给想参赛的新人 <a class="header-anchor" href="#三、给想参赛的新人" aria-label="Permalink to &quot;三、给想参赛的新人&quot;">​</a></h2><h3 id="学习路线建议" tabindex="-1">学习路线建议 <a class="header-anchor" href="#学习路线建议" aria-label="Permalink to &quot;学习路线建议&quot;">​</a></h3><p>如果让我重新准备，我会按“先建立整体认识 → 深入源码 → 横向比较 → 测试与优化 → 参赛实践”的路线来学。</p><ul><li>核心工具：AI 讲解、AI 检索、检索工具、相关帖子社区、官方文档、<strong>流程图等示意图</strong>。</li><li>参考项目：前期最好以一个开源项目为参考，对照源码进行梳理。</li></ul><h4 id="学习步骤" tabindex="-1">学习步骤 <a class="header-anchor" href="#学习步骤" aria-label="Permalink to &quot;学习步骤&quot;">​</a></h4><ol><li><strong>建立系统架构认知</strong>：先梳理清楚数据库内核的系统架构，搞明白整个系统是怎么串联起来的，对整个框架有清晰认识；明确数据库内核开发涉及哪些模块、每个模块是干什么的、职责边界在哪。</li><li><strong>深入源码实现</strong>：深入各个模块，学习数据结构、核心 API 接口、算法。</li><li><strong>横向对比实现策略</strong>：看完一个完整的开源仓库后，相当于有了一个版本的实现。接下来做比较全面的理论学习，了解各个模块的所有实现策略，横向对比分析，并理解不同实现策略的适用场景。</li><li><strong>测试与性能分析</strong>：在继续梳理不同模块、让理解更具体的同时，学习如何做性能测试、如何分析性能指标。</li><li><strong>沉淀优化方法论</strong>：总结优化过程中的常见优化手段、策略。</li></ol><h4 id="学完后再参赛" tabindex="-1">学完后再参赛 <a class="header-anchor" href="#学完后再参赛" aria-label="Permalink to &quot;学完后再参赛&quot;">​</a></h4><ul><li>整个理论学习搞完后，再来参赛实践，会有不同的感受，远比从零开始直接用 AI 参赛更有效率。</li><li>也可以边参赛边学，但经过完整的理论学习之后，才能更好地驾驭 AI、掌握代码，效率更高，能力更强。</li></ul><h4 id="时间预期与检验标准" tabindex="-1">时间预期与检验标准 <a class="header-anchor" href="#时间预期与检验标准" aria-label="Permalink to &quot;时间预期与检验标准&quot;">​</a></h4><ul><li>理论学习大概持续 1 个月，需要长期沉淀磨砺、反复分析理解。</li><li>最终的检验标准：能够脱稿讲清楚整个系统的架构、各个模块的实现；能够给别人讲清楚整个“流程”；提到哪个部分都能讲出是怎么回事、要注意哪些点。</li><li>达到这种状态后，拿奖基本是板上钉钉的事，保底二等奖。</li></ul><h3 id="学习资源与技巧" tabindex="-1">学习资源与技巧 <a class="header-anchor" href="#学习资源与技巧" aria-label="Permalink to &quot;学习资源与技巧&quot;">​</a></h3><p>学习资源方面，主要靠：AI 讲解、AI 检索、GitHub 开源仓库、学长交流、助教交流、官方文档。</p><p>一些学习技巧：</p><ul><li>了解缩写的全称；</li><li>梳理清楚具体的物理层面的存储逻辑；</li><li>结合可视化示意图（mermaid、ASCII 可视化）理解；</li><li>搞清楚模块之间的协作；</li><li>哪里不懂马上问 AI、反复问、记录下问题，同步队友之间的疑问，多交流提问，相互讲解；</li><li>学懂的特征是“讲”懂；输出的文档什么样就学成什么样。</li></ul><blockquote><p>用笔记/文档把学习内容可视化很耗 token，Deepseek 消费估计得三位数。 个人 deepseek token 消费情况：6 月 15 亿，7 月 25.6 亿，8 月到比赛结束 25 亿。token 消费在 500+ RMB，最近价格也上涨了，消费只会更多。</p></blockquote><h3 id="备赛建议" tabindex="-1">备赛建议 <a class="header-anchor" href="#备赛建议" aria-label="Permalink to &quot;备赛建议&quot;">​</a></h3><p>先说说备赛的总体原则：提前准备、高质量、真的会。赛事估计每年都在调整、改革，每年的经验可能不适用了，所以更重要的是方法论、本身的学习能力。</p><p>比赛的挑战主要体现在：</p><ul><li>团队协作能力（分工 -&gt; 落实），统一规范</li><li>表达能力（开会分享内容、讲解代码的表达能力、梳理内容的思路）。根据我的观察，存在表达能力薄弱，讲解内容没思路、混乱的情况。开会讲解的时候，半天讲不明白，梳理不清楚，不如问 AI。(讲解表达能力弱的，可以考虑总结成文档，分享文档)</li><li>大量的时间需要思考、学习。该比赛对于专业能力要求还是非常有挑战的，涉及到源码，涉及到大量的数据结构、算法知识，对于计算机基础有较高的要求。</li></ul><h3 id="适合参赛人群" tabindex="-1">适合参赛人群 <a class="header-anchor" href="#适合参赛人群" aria-label="Permalink to &quot;适合参赛人群&quot;">​</a></h3><p>最适合大一同学参加，收获最大，其次是大二，大三大四不推荐，但也可以尝试。</p><p>大一同学的特征：</p><ul><li>工程能力薄弱，没有管理过项目、没有团队协作经验</li><li>刚入门了编程语言，需要更加深刻的理解</li><li>对于计算机理论基础比较薄弱，甚至没有基础</li><li>对于数据结构不了解，对于算法不了解</li><li>时间充裕，学习压力小，容错率更高</li><li></li></ul><p>大一大二适合的理由：这个阶段基础能力比较弱，但是有 AI 的帮助，90% 的基础能力的欠缺都可以在 AI 的讲解下补齐，在比赛中学习比&quot;上课&quot;、&quot;自己做项目&quot;实践锻炼收获更大，是快速提升计算机能力不错的途径，把这个比赛打明白了，整个大学的计算机能力基本上就过关了，可以自己做职业规划，往专精领域发展了。</p><h2 id="四、给主办方的建议" tabindex="-1">四、给主办方的建议 <a class="header-anchor" href="#四、给主办方的建议" aria-label="Permalink to &quot;四、给主办方的建议&quot;">​</a></h2><h3 id="真实感受" tabindex="-1">真实感受 <a class="header-anchor" href="#真实感受" aria-label="Permalink to &quot;真实感受&quot;">​</a></h3><p>作为参赛者，观察到的情况包括：</p><ul><li>全流程过度依赖 AI，线上线下比赛都依赖 AI，比赛筛选出来的队伍肯定也存在一定的问题。比赛的评价评审标准需要调整。</li><li>初赛阶段的线上评测系统存在一定的问题(后来修复过)</li><li>其他队伍失败的原因可能是： <ul><li>比赛时间周期长，不愿投入；</li><li>门槛高，代码看不懂，畏难；</li><li>用不明白 AI；</li><li>初赛评测服务器的影响</li><li>...</li></ul></li></ul><h3 id="具体的建议" tabindex="-1">具体的建议 <a class="header-anchor" href="#具体的建议" aria-label="Permalink to &quot;具体的建议&quot;">​</a></h3><p>原则：降低所有能利用 AI 完成的阶段，的得分权重。</p><h4 id="性能优化阶段" tabindex="-1">性能优化阶段 <a class="header-anchor" href="#性能优化阶段" aria-label="Permalink to &quot;性能优化阶段&quot;">​</a></h4><p>不公布具体性能分数排名，只给模糊的性能百分比。</p><p>举例：将排名按照不同的梯队分成不同的等级，分为 A/B/C/D/E 等不同的梯队，A 等级的分数在 80-100 分，B 等级的分数在 60-80 分，以此类推。</p><p>一定程度上，将比赛的注意力从无底线的刷分上，转移到其他方面的准备上。</p><p>为什么要削弱分差的影响？</p><p>线上赛，可以使用 AI 来完成优化，只要性能分差就足够高，就可以大幅度削弱其他竞争选手的得分。只要有一个队伍把分数拉到了前所未有的高度，那么其他队伍就会感到分数差距带来的压力，被迫也用 AI 快速刷分。</p><p>除非，比赛的举办目的就是为了让选手造一个高性能的数据库出来，那么这么搞是有效的，但是，比赛的参赛对象都是本科生，本身能力有限、时间有限，为了获奖，那么使用 AI 刷分无疑是最高效的手段。</p><p>所以，性能优化导致的分数差距是一个极度影响比赛不平衡的方面，大大削弱了选手真正动手实践的意愿。</p><p>不对分差设限制，随着 AI 模型能力的升级，最终的结果只有一个，那就是：所有队伍的优化策略往&quot;工业级&quot;数据库、&quot;最优&quot;数据库靠齐，分数来到一个机器承载的最高临界点。没有什么所谓的创新、能力培养，毕竟，只需要用 AI 完成优化，然后准备 PPT 答辩就足够了。</p><h4 id="答辩环节" tabindex="-1">答辩环节 <a class="header-anchor" href="#答辩环节" aria-label="Permalink to &quot;答辩环节&quot;">​</a></h4><ul><li>增大答辩权重：答辩是真正能够有效考验一个队伍对于数据库理解的环节，是否真的实践过数据库的开发，多提几个问题就能看出来，是否真的懂原理，是否真的知道如何分析、解决问题。</li><li>丰富答辩环节的提问： <ul><li>场景设计问题，考查临场分析。假设给出了各个指标的值、各个模块的实现策略，可以考虑怎么优化，优化哪些模块，使用哪些手段优化。只有有经验、真实实践过的才能讲得出来。</li><li>追问策略的实现细节，具体是怎么实现的，为什么不用别的实现，如果不用这个策略，还有哪些策略可以实现可以用来优化的。</li><li>团队协作分工情况，是否真正分工了，怎么分配工作的</li></ul></li><li>允许答辩选手画图讲解演示说明</li></ul><h4 id="线下编程赛环节" tabindex="-1">线下编程赛环节 <a class="header-anchor" href="#线下编程赛环节" aria-label="Permalink to &quot;线下编程赛环节&quot;">​</a></h4><ul><li>线下比赛不允许携带资料(主办方准备固定代码框架)</li><li>考查解决问题的完整流程：发现问题(报错信息，报错定位，打断点调试)，分析问题，解决问题</li><li>题目类型多样性：完整实现功能、填空题代码补全等类型</li></ul><p>多出几个题目，既要从零实现，也要 debug。</p><h4 id="赛事制度" tabindex="-1">赛事制度 <a class="header-anchor" href="#赛事制度" aria-label="Permalink to &quot;赛事制度&quot;">​</a></h4><blockquote><p>听了专家精彩分享之后有感：线下交流的重要性</p></blockquote><p>赛制调整</p><ol><li>线上：初赛功能实现 + 初赛优化</li><li>Gap</li><li>线下：编程赛 + 答辩</li><li>线上：决赛优化阶段</li><li>Gap</li><li>线下答辩</li></ol><p>调整理由：</p><ul><li>Gap 的意思是，中间有充足的间隔时间，不同的阶段准备不同的内容，不要既完成优化，又完成答辩，时间协调极度不合理</li><li>资格提前：既然比赛有门槛，门槛一：通过初赛的所有功能题目实现；门槛二：线下编程赛，那为何不提前把门槛都通过了？初赛有一个门槛，决赛还有门槛，多此一举，直接在初赛阶段就把所有门槛全都过了，对主办方对参赛选手都好。</li><li>两轮答辩：初衷是两次机会，大部分同学没有比赛经验，如果在决赛前提前有一轮线下交流接受指导的机会，决赛会表现得更好，优化更有方向，答辩更得心应手。既能选拔、又能培养。</li></ul><h4 id="其他方面" tabindex="-1">其他方面 <a class="header-anchor" href="#其他方面" aria-label="Permalink to &quot;其他方面&quot;">​</a></h4><ul><li>更多学习资源：引导学习路线，分享比赛经验，活跃社区</li><li>增加考查方面，目前过于单一，考查力度不够。</li><li>改善比赛体验，例如测试结果保存，查看历史评测结果。</li><li>更完善的官方比赛说明，补充缺漏的关键信息说明。</li><li>初赛功能题目的格式没有统一，有的是纯 html ，有的题目是 md 转 html 。</li></ul><h2 id="五、附录" tabindex="-1">五、附录 <a class="header-anchor" href="#五、附录" aria-label="Permalink to &quot;五、附录&quot;">​</a></h2><h3 id="线下赛题目" tabindex="-1">线下赛题目 <a class="header-anchor" href="#线下赛题目" aria-label="Permalink to &quot;线下赛题目&quot;">​</a></h3><p>2025 年：实现 left join 2026 年：实现 intersect</p><h3 id="答辩记录" tabindex="-1">答辩记录 <a class="header-anchor" href="#答辩记录" aria-label="Permalink to &quot;答辩记录&quot;">​</a></h3><p>我们队伍的答辩过程大致是这样：</p><ul><li>一轮答辩提问： <ul><li>优化提升最大的策略是什么？</li><li>哪个优化手段最具创新性？</li><li>最大的困难是什么？</li><li>针对索引缓存复用具体是怎么做的？怎么命中的？...</li></ul></li><li>二轮答辩提问： <ul><li>关于锁的提问。</li><li>关于轻量检查点，哪里体现出轻量的？什么情况下会触发？</li><li>谈谈自己的感受。</li></ul></li></ul><h3 id="优化技术统计" tabindex="-1">优化技术统计 <a class="header-anchor" href="#优化技术统计" aria-label="Permalink to &quot;优化技术统计&quot;">​</a></h3><p>最后附上我们整理过的优化技术统计，供参考：</p><ul><li>查询优化器： <ul><li>逻辑优化： <ul><li>谓词下推。</li><li>等值谓词传播。</li><li>重复条件消除。</li><li>矛盾条件检测。</li></ul></li><li>物理优化： <ul><li>基于代价的计划生成。</li></ul></li><li>计划缓存优化。</li><li>索引的正确使用。</li></ul></li><li>存储： <ul><li>组提交：减少 fdatasync 次数。</li><li>I/O 控制：例如优先提交所需的 fdatasync。</li><li>缓冲区： <ul><li>减少锁竞争。</li><li>并行访问。</li></ul></li><li>双 WAL 缓冲池。</li></ul></li></ul><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h3><p>这次比赛从 5 月打到 8 月，过程很长，也有很多值得复盘的地方。虽然我大量依赖了 AI，也踩了不少坑，但正是这些经历让我对数据库内核、AI 协作、工程能力有了更具体的认识。</p><p>如果你也准备参加，希望这篇分享能帮你少走一点弯路。祝后来的参赛者都能真正学到东西，也拿到自己想要的结果。</p><h3 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h3><ul><li>比赛入口：<a href="https://os.educg.net/#/index?TYPE=26DB" target="_blank" rel="noreferrer">https://os.educg.net/#/index?TYPE=26DB</a></li><li>GitHub 开源仓库： <ul><li>测试框架：<a href="https://github.com/db-camp/TPCC-Tester" target="_blank" rel="noreferrer">https://github.com/db-camp/TPCC-Tester</a></li><li>2024-Kosthi：<a href="https://github.com/Kosthi/CSCC-DB-Rucbase-2024" target="_blank" rel="noreferrer">https://github.com/Kosthi/CSCC-DB-Rucbase-2024</a></li><li>2025-明泰：<a href="https://github.com/RushDB-Lab/CSCC-DB-Rucbase-2025" target="_blank" rel="noreferrer">https://github.com/RushDB-Lab/CSCC-DB-Rucbase-2025</a></li></ul></li></ul>',139)])])}const b=a(t,[["render",h]]);export{p as __pageData,b as default};
